         'use strict';

         // ── 1. UTILITIES ─────────────────────────────────────────
         /**
          * Seleciona um elemento pelo seletor CSS
           * @param {string} sel
            * @param {Document|Element} [ctx=document]
             */
             const $ = (sel, ctx = document) => ctx.querySelector(sel);

             /**
              * Seleciona todos os elementos pelo seletor CSS
               * @param {string} sel
                * @param {Document|Element} [ctx=document]
                 */
                 const $$ = (sel, ctx = document) => [...ctx.querySelectorAll(sel)];

                 // ── 2. HEADER – scroll behaviour ─────────────────────────
                 (function initHeader() {
                   const header = $('#siteHeader');
                     if (!header) return;

                       const onScroll = () => {
                           header.classList.toggle('scrolled', window.scrollY > 10);
                             };

                               window.addEventListener('scroll', onScroll, { passive: true });
                                 onScroll();
                                 })();

                                 // ── 3. NAV – hamburger mobile ─────────────────────────────
                                 (function initNav() {
                                   const btn  = $('#navHamburger');
                                     const menu = $('#navMenu');
                                       if (!btn || !menu) return;

                                         const toggle = (force) => {
                                             const isOpen = force !== undefined ? force : !menu.classList.contains('open');
                                                 menu.classList.toggle('open', isOpen);
                                                     btn.classList.toggle('active', isOpen);
                                                         btn.setAttribute('aria-expanded', String(isOpen));
                                                           };

                                                             btn.addEventListener('click', () => toggle());

                                                               // Fechar ao clicar em um link
                                                                 $$('a', menu).forEach(link => {
                                                                     link.addEventListener('click', () => toggle(false));
                                                                       });

                                                                         // Fechar com Escape
                                                                           document.addEventListener('keydown', e => {
                                                                               if (e.key === 'Escape') toggle(false);
                                                                                 });
                                                                                 })();

                                                                                 // ── 4. REVEAL ON SCROLL (IntersectionObserver) ───────────
                                                                                 (function initReveal() {
                                                                                   const elements = $$('.reveal');
                                                                                     if (!elements.length) return;

                                                                                       const observer = new IntersectionObserver(
                                                                                           (entries) => {
                                                                                                 entries.forEach((entry, i) => {
                                                                                                         if (entry.isIntersecting) {
                                                                                                                   // Pequeno delay escalonado por grupo
                                                                                                                             const delay = (i % 4) * 80;
                                                                                                                                       setTimeout(() => {
                                                                                                                                                   entry.target.classList.add('visible');
                                                                                                                                                             }, delay);
                                                                                                                                                                       observer.unobserve(entry.target);
                                                                                                                                                                               }
                                                                                                                                                                                     });
                                                                                                                                                                                         },
                                                                                                                                                                                             { threshold: 0.12, rootMargin: '0px 0px -40px 0px' }
                                                                                                                                                                                               );

                                                                                                                                                                                                 elements.forEach(el => observer.observe(el));
                                                                                                                                                                                                 })();

                                                                                                                                                                                                 // ── 5. HERO CANVAS – partículas flotantes ────────────────
                                                                                                                                                                                                 (function initHeroCanvas() {
                                                                                                                                                                                                   const canvas = $('#heroCanvas');
                                                                                                                                                                                                     if (!canvas) return;

                                                                                                                                                                                                       // Respeitar prefers-reduced-motion
                                                                                                                                                                                                         if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
                                                                                                                                                                                                             canvas.style.display = 'none';
                                                                                                                                                                                                                 return;
                                                                                                                                                                                                                   }

                                                                                                                                                                                                                     const ctx = canvas.getContext('2d');
                                                                                                                                                                                                                       let W, H, particles;

                                                                                                                                                                                                                         const ICONS = ['🌾', '⚓', '🌱', '🚢', '🌊', '🌿'];

                                                                                                                                                                                                                           class Particle {
                                                                                                                                                                                                                               constructor() { this.reset(true); }

                                                                                                                                                                                                                                   reset(initial = false) {
                                                                                                                                                                                                                                         this.x    = Math.random() * W;
                                                                                                                                                                                                                                               this.y    = initial ? Math.random() * H : H + 20;
                                                                                                                                                                                                                                                     this.size = Math.random() * 14 + 8;
                                                                                                                                                                                                                                                           this.speed = Math.random() * 0.4 + 0.15;
                                                                                                                                                                                                                                                                 this.opacity = Math.random() * 0.4 + 0.05;
                                                                                                                                                                                                                                                                       this.icon  = ICONS[Math.floor(Math.random() * ICONS.length)];
                                                                                                                                                                                                                                                                             this.drift = (Math.random() - 0.5) * 0.3;
                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                     update() {
                                                                                                                                                                                                                                                                                           this.y -= this.speed;
                                                                                                                                                                                                                                                                                                 this.x += this.drift;
                                                                                                                                                                                                                                                                                                       if (this.y < -30) this.reset();
                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                               draw() {
                                                                                                                                                                                                                                                                                                                     ctx.save();
                                                                                                                                                                                                                                                                                                                           ctx.globalAlpha = this.opacity;
                                                                                                                                                                                                                                                                                                                                 ctx.font        = `${this.size}px serif`;
                                                                                                                                                                                                                                                                                                                                       ctx.fillText(this.icon, this.x, this.y);
                                                                                                                                                                                                                                                                                                                                             ctx.restore();
                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                   }

                                                                                                                                                                                                                                                                                                                                                     const resize = () => {
                                                                                                                                                                                                                                                                                                                                                         W = canvas.width  = canvas.offsetWidth;
                                                                                                                                                                                                                                                                                                                                                             H = canvas.height = canvas.offsetHeight;
                                                                                                                                                                                                                                                                                                                                                                 particles = Array.from({ length: 30 }, () => new Particle());
                                                                                                                                                                                                                                                                                                                                                                   };

                                                                                                                                                                                                                                                                                                                                                                     let raf;
                                                                                                                                                                                                                                                                                                                                                                       const loop = () => {
                                                                                                                                                                                                                                                                                                                                                                           ctx.clearRect(0, 0, W, H);
                                                                                                                                                                                                                                                                                                                                                                               particles.forEach(p => { p.update(); p.draw(); });
                                                                                                                                                                                                                                                                                                                                                                                   raf = requestAnimationFrame(loop);
                                                                                                                                                                                                                                                                                                                                                                                     };

                                                                                                                                                                                                                                                                                                                                                                                       window.addEventListener('resize', resize);
                                                                                                                                                                                                                                                                                                                                                                                         resize();
                                                                                                                                                                                                                                                                                                                                                                                           loop();

                                                                                                                                                                                                                                                                                                                                                                                             // Pausar quando fora da viewport
                                                                                                                                                                                                                                                                                                                                                                                               const heroObserver = new IntersectionObserver(([entry]) => {
                                                                                                                                                                                                                                                                                                                                                                                                   if (entry.isIntersecting) {
                                                                                                                                                                                                                                                                                                                                                                                                         raf = requestAnimationFrame(loop);
                                                                                                                                                                                                                                                                                                                                                                                                             } else {
                                                                                                                                                                                                                                                                                                                                                                                                                   cancelAnimationFrame(raf);
                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                         });
                                                                                                                                                                                                                                                                                                                                                                                                                           heroObserver.observe(canvas.closest('.hero'));
                                                                                                                                                                                                                                                                                                                                                                                                                           })();

                                                                                                                                                                                                                                                                                                                                                                                                                           // ── 6. COUNTER ANIMADO (stats no hero) ───────────────────
                                                                                                                                                                                                                                                                                                                                                                                                                           (function initCounters() {
                                                                                                                                                                                                                                                                                                                                                                                                                             const nums = $$('[data-target]');
                                                                                                                                                                                                                                                                                                                                                                                                                               if (!nums.length) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                 const easeOut = t => 1 - Math.pow(1 - t, 3);

                                                                                                                                                                                                                                                                                                                                                                                                                                   const animateCounter = (el) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                       const target   = parseFloat(el.dataset.target);
                                                                                                                                                                                                                                                                                                                                                                                                                                           const duration = 1800;
                                                                                                                                                                                                                                                                                                                                                                                                                                               const start    = performance.now();

                                                                                                                                                                                                                                                                                                                                                                                                                                                   const step = (now) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                         const progress = Math.min((now - start) / duration, 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                               const value    = easeOut(progress) * target;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                     el.textContent = target % 1 === 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                             ? Math.round(value)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     : value.toFixed(1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (progress < 1) requestAnimationFrame(step);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   requestAnimationFrame(step);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const observer = new IntersectionObserver(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           (entries) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 entries.forEach(entry => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (entry.isIntersecting) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   animateCounter(entry.target);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             observer.unobserve(entry.target);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   { threshold: 0.5 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       nums.forEach(n => observer.observe(n));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       })();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // ── 7. ACESSIBILIDADE ─────────────────────────────────────
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       (function initAccessibility() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const bar      = $('#accessBar');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const toggle   = $('#accessToggle');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const btnUp    = $('#btnFontUp');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const btnDown  = $('#btnFontDown');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const btnContr = $('#btnContrast');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (!bar || !toggle) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     let scale = parseFloat(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         localStorage.getItem('fontScale') || '1'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             let contrast = localStorage.getItem('contrast') === 'true';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // Aplicar estado salvo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 document.documentElement.style.setProperty('--font-scale', scale);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   document.body.classList.toggle('high-contrast', contrast);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     toggle.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const isOpen = bar.classList.toggle('open');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             toggle.setAttribute('aria-expanded', String(isOpen));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (btnUp) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     btnUp.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           scale = Math.min(scale + 0.1, 1.5);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 document.documentElement.style.setProperty('--font-scale', scale);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       localStorage.setItem('fontScale', scale);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (btnDown) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   btnDown.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         scale = Math.max(scale - 0.1, 0.8);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               document.documentElement.style.setProperty('--font-scale', scale);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     localStorage.setItem('fontScale', scale);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             if (btnContr) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 btnContr.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       contrast = !contrast;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             document.body.classList.toggle('high-contrast', contrast);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   localStorage.setItem('contrast', contrast);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         })();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         // ── 8. SUSTENTABILIDADE – cards expansíveis ──────────────
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         (function initSustCards() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const headers = $$('.sust-card-header');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             headers.forEach(header => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const bodyId = header.getAttribute('aria-controls');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const body   = bodyId ? document.getElementById(bodyId) : null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         if (!body) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             header.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const expanded = header.getAttribute('aria-expanded') === 'true';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         // Fechar todos os outros
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               headers.forEach(h => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const bid = h.getAttribute('aria-controls');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const b   = bid ? document.getElementById(bid) : null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (h !== header) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 h.setAttribute('aria-expanded', 'false');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (b) b.hidden = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // Toggle o atual
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     header.setAttribute('aria-expanded', String(!expanded));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           body.hidden = expanded;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 })();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 // ── 9. CURIOSIDADES ───────────────────────────────────────
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 (function initCuriosidades() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const facts = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       { icon: '🌾', text: 'O Porto de Paranaguá movimenta cerca de 50 milhões de toneladas de carga por ano, sendo a maior parte composta por soja, milho e farelo de soja — todos produzidos no interior do Paraná.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           { icon: '⚓', text: 'O Porto de Paranaguá foi fundado em 1648, tornando-se um dos portos mais antigos das Américas. Hoje é o maior porto graneleiro da América Latina e o 2º maior exportador de grãos do hemisfério sul.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               { icon: '🐬', text: 'O boto-cinza (Sotalia guianensis) vive na Baía de Paranaguá e convive com um dos maiores portos do mundo. Sua presença é monitorada pela UFPR como indicador de qualidade ambiental da baía.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   { icon: '🌱', text: 'O Paraná é responsável por cerca de 20% da produção nacional de soja, sendo o 2º maior produtor do Brasil. A maior parte dos grãos é exportada pelo Porto de Paranaguá.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       { icon: '🚢', text: 'Mais de 3.500 navios atracam no Porto de Paranaguá todos os anos, conectando o agronegócio paranaense a mais de 60 países em todos os continentes, da China à Europa.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           { icon: '🌿', text: 'O plantio direto, técnica usada em mais de 70% das lavouras paranaenses, evita o revolvimento do solo. Isso reduz a erosão, mantém a umidade e sequestra carbono — ajudando a combater as mudanças climáticas.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               { icon: '🦅', text: 'O estuário da Baía de Paranaguá é o maior do Brasil e um dos maiores do mundo. Abriga mais de 100 espécies de peixes, 600 espécies de aves e extensos manguezais que protegem a costa e filtram a água.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   { icon: '🚛', text: 'O corredor logístico Paraná–Paranaguá é um dos mais movimentados do mundo. Nos períodos de pico de safra, mais de 2.000 caminhões graneleiros chegam ao porto diariamente.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       { icon: '🔬', text: 'Satélites e drones agrícolas permitem que produtores paranaenses monitorem lavouras em tempo real, aplicando fertilizantes e defensivos apenas onde são necessários, reduzindo custos e impacto ambiental em até 40%.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           { icon: '💧', text: 'O Paraná possui uma das maiores redes de monitoramento de bacias hidrográficas do Brasil. O controle garante que a captação de água para irrigação não comprometa os rios que deságuam na Baía de Paranaguá.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               { icon: '🌍', text: 'O Brasil é o maior exportador mundial de soja e o Paraná é peça fundamental nessa história. Parte significativa da proteína animal consumida na Europa, China e Oriente Médio vem de grãos exportados pelo Porto de Paranaguá.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   { icon: '⚡', text: 'O Programa Porto Verde da APPA investe em eletrificação de berços de atracação, o que permite que navios desliguem seus motores enquanto estão no porto, reduzindo significativamente as emissões de gases poluentes.' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const icon  = $('#curIcon');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const text  = $('#curText');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const num   = $('#curNum');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const btn   = $('#curBtn');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               if (!icon || !text || !btn) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 let current = -1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const order = facts.map((_, i) => i);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     // Embaralhar array
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       for (let i = order.length - 1; i > 0; i--) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const j = Math.floor(Math.random() * (i + 1));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               [order[i], order[j]] = [order[j], order[i]];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   btn.addEventListener('click', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       current = (current + 1) % facts.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const fact = facts[order[current]];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // Animação de troca
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   icon.style.animation = 'none';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       // eslint-disable-next-line no-unused-expressions
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           icon.offsetHeight; // reflow
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               icon.style.animation = 'iconPop 0.4s var(--ease-spring)';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   icon.textContent = fact.icon;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       text.textContent = fact.text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           num.textContent  = `${current + 1} / ${facts.length}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             })();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             // ── 10. CARROSSEL DE IMAGENS ──────────────────────────────
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             (function initCarousel() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const track  = $('#carouselTrack');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const prevBtn = $('#carPrev');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const nextBtn = $('#carNext');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const dotsBox = $('#carDots');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (!track) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const slides = $$('.carousel-slide', track);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           const total  = slides.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             let current  = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               let autoTimer;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 // Criar dots
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (dotsBox) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       slides.forEach((_, i) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const dot = document.createElement('button');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   dot.className = `carousel-dot${i === 0 ? ' active' : ''}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         dot.setAttribute('role', 'tab');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               dot.setAttribute('aria-label', `Imagem ${i + 1} de ${total}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     dot.setAttribute('aria-selected', String(i === 0));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           dot.addEventListener('click', () => goTo(i));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 dotsBox.appendChild(dot);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         const goTo = (idx) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             current = (idx + total) % total;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 track.style.transform = `translateX(-${current * 100}%)`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if (dotsBox) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           $$('.carousel-dot', dotsBox).forEach((d, i) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   d.classList.toggle('active', i === current);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           d.setAttribute('aria-selected', String(i === current));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         // Atualizar aria para acessibilidade
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             slides.forEach((s, i) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   s.setAttribute('aria-hidden', String(i !== current));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           resetAuto();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const resetAuto = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   clearInterval(autoTimer);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       autoTimer = setInterval(() => goTo(current + 1), 5000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           prevBtn && prevBtn.addEventListener('click', () => goTo(current - 1));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             nextBtn && nextBtn.addEventListener('click', () => goTo(current + 1));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // Swipe / touch
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 let touchStartX = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   track.addEventListener('touchstart', e => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       touchStartX = e.touches[0].clientX;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }, { passive: true });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           track.addEventListener('touchend', e => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const diff = touchStartX - e.changedTouches[0].clientX;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (Math.abs(diff) > 50) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         goTo(diff > 0 ? current + 1 : current - 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 // Teclado
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   track.closest('.carousel').addEventListener('keydown', e => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (e.key === 'ArrowLeft')  goTo(current - 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (e.key === 'ArrowRight') goTo(current + 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // Pausar quando hover
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 track.closest('.carousel').addEventListener('mouseenter', () => clearInterval(autoTimer));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   track.closest('.carousel').addEventListener('mouseleave', resetAuto);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     goTo(0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     })();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     // ── 11. QUIZ ──────────────────────────────────────────────
